insert into public.tipos_laudo (id, codigo, nome, descricao, ordem, ativo) values
  ('16cf2b57-f83a-5e49-beb4-de5aab7986dd', 'securitario', 'Securitário (perícia para seguradoras)', 'Laudo médico-pericial judicial na área securitária conforme diretriz da ABMLPM: seguro de vida/morte, IPA, IFPD, DIT, DIH, doenças graves, SPVAT e outras coberturas. Mantém rastreabilidade entre contrato/apólice, evento/sinistro, condição médica, dano, nexo causal, funcionalidade e conclusão médico-pericial. Módulos condicionais por cobertura em análise (XIX-A..G). O laudo fornece elementos médicos, funcionais, causais e temporais; a interpretação jurídica das cláusulas compete ao Juízo.', 8, true);
